<?php
namespace App\Http\Controllers; use App\Models\Agenda; use App\Models\Contact; use App\Models\Meeting; use App\Models\User; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class MeetingController extends Controller { public function create():View{return view('meetings.create',['agendas'=>Agenda::orderBy('title')->get(['id','title','pre_event_plan_id']),'contacts'=>Contact::orderBy('name')->get(['id','name','mobile_1'])]);} public function store(Request $request):RedirectResponse{$data=$request->validate(['title'=>['required','string','max:255'],'meeting_at'=>['required','date'],'attendee_ids'=>['nullable','array'],'attendee_ids.*'=>['integer','exists:contacts,id'],'agenda_ids'=>['nullable','array'],'agenda_ids.*'=>['integer','exists:agendas,id'],'remarks'=>['nullable','string','max:5000'],'status'=>['required','in:upcoming,ongoing,done,cancelled']]);$data['called_by_id']=$request->user()->id;Meeting::create($data);return redirect()->route('meetings.index')->with('success','Meeting saved successfully.');} public function index(Request $request):View{$filters=$request->validate(['status'=>['nullable','in:upcoming,ongoing,done,cancelled'],'user'=>['nullable','integer','exists:users,id'],'search'=>['nullable','string','max:255']]);$meetings=Meeting::with('calledBy')->when($filters['status']??null,fn($q,$x)=>$q->where('status',$x))->when($filters['user']??null,fn($q,$x)=>$q->where('called_by_id',$x))->when($filters['search']??null,fn($q,$x)=>$q->where('title','like',"%{$x}%"))->latest('meeting_at')->paginate(20)->withQueryString();return view('meetings.index',['meetings'=>$meetings,'filters'=>$filters,'users'=>User::where('is_active',true)->orderBy('name')->get(['id','name'])]);} }
